const csp="object-src 'none'; script-src 'self' 'sha256-medd45OwaiaiwMzybrJ/Qa/ksFMKOAsrpOvgikCUTWE='; style-src 'self' 'unsafe-inline'; base-uri 'self'; default-src 'self'; img-src 'self' data:; connect-src 'self' https://*.wikipedia.org https://www.wikidata.org https://commons.wikimedia.org https://upload.wikimedia.org https://collectionapi.metmuseum.org https://images.metmuseum.org; worker-src 'self'; manifest-src 'self'; frame-ancestors 'none'; form-action 'self'";
export default {
  async fetch(request) {
    const path = new URL(request.url).pathname;
    if (!['GET', 'HEAD'].includes(request.method)) return new Response('Method not allowed', {status: 405, headers: {Allow: 'GET, HEAD'}});
    if (path === '/health') return Response.json({status: 'ok', version: '0.11.0'});
    const asset = assets[path];
    if (!asset) return new Response('Not found', {status: 404});
    const bytes = Uint8Array.from(atob(asset.body), c => c.charCodeAt(0));
    return new Response(request.method === 'HEAD' ? null : bytes, {encodeBody: 'manual', headers: {
      'Content-Type': asset.type,
      'Content-Encoding': 'gzip',
      'Cache-Control': path.startsWith('/_app/immutable/') ? 'public, max-age=31536000, immutable' : 'no-cache',
      'X-Content-Type-Options': 'nosniff',
      'Referrer-Policy': 'same-origin',
      'Content-Security-Policy': csp
    }});
  }
};
